const root = document.querySelector('#app');
const config = window.WORKTIME_CONFIG;
const today = () => new Date().toISOString().slice(0, 10);
const HOLIDAYS = new Set(['2026-01-01','2026-04-03','2026-04-06','2026-05-01','2026-05-14','2026-05-25','2026-06-04','2026-10-03','2026-11-01','2026-12-25','2026-12-26']);
const MENU = [['time','Zeiterfassung'],['orders','Arbeitsscheine'],['calendar','Kalender'],['customers','Kunden'],['materials','Materialliste'],['billing','Abrechnungen Kunden'],['invoices','Rechnungen'],['mail','Postfach'],['settings','Einstellungen']];
const defaultPermissions = { time:true, customers:true, orders:true, calendar:true };

if (!config?.supabaseUrl || !config?.supabasePublishableKey) {
  root.innerHTML = '<main class="loading">Die App-Konfiguration ist nicht verfügbar.</main>';
  throw new Error('Konfiguration fehlt');
}
let db;
const state = { session:null, profile:null, people:[], data:emptyData(), view:'time', date:today(), month:new Date().getMonth(), year:new Date().getFullYear(), menu:false, selectedEmployeeId:null, selectedBusinessId:null, selectedCustomerId:null, folder:'all', openMessageId:null, busy:false, syncing:false, toast:null, booting:true };
function emptyData(){ return {customers:[], entries:[], days:[], orders:[], items:[], materials:[], messages:[], vacations:[], appointments:[], documents:[], payslips:[]}; }
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const num = value => { const n = Number(String(value ?? '').replace(',','.')); return Number.isFinite(n) ? n : 0; };
const hours = value => `${num(value).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})} h`;
const timeLabel = value => value ? `${String(value).slice(0,5)} Uhr` : '–';
const dateLabel = value => new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(`${value}T12:00:00`));
const compactDate = value => new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit'}).format(new Date(`${value}T12:00:00`));
const iso = d => d.toISOString().slice(0,10);
const dayDate = value => new Date(`${value}T12:00:00`);
const same = (a,b) => String(a ?? '') === String(b ?? '');
const normalize = value => String(value ?? '').trim().toLocaleLowerCase('de-DE').replace(/\s+/g,' ');
const manager = () => ['administrator','business'].includes(state.profile?.role);
const admin = () => state.profile?.role === 'administrator';
const business = () => state.profile?.role === 'business';
const businesses = () => state.people.filter(p => p.role === 'business');
const currentBusinessId = () => admin() ? (state.selectedBusinessId || '') : business() ? state.profile.id : (state.profile?.business_id || '');
const activeBusiness = () => state.people.find(p => p.role === 'business' && same(p.id,currentBusinessId()));
const employeePeople = () => state.people.filter(p => p.role === 'employee' && same(p.business_id,currentBusinessId()));
const selectablePeople = () => {
  if (!state.profile) return [];
  const candidates = admin() ? [state.profile, activeBusiness(), ...employeePeople()] : business() ? [state.profile, ...employeePeople()] : [state.profile];
  return candidates.filter((person,index,list) => person && list.findIndex(other => same(other.id,person.id)) === index);
};
const activeEmployeeId = () => {
  if (!state.profile) return '';
  const candidates = selectablePeople();
  if (state.selectedEmployeeId && candidates.some(person => same(person.id,state.selectedEmployeeId))) return state.selectedEmployeeId;
  return state.profile.id;
};
const activePerson = () => state.people.find(p => same(p.id,activeEmployeeId())) || state.profile;
const activeName = () => activePerson()?.display_name || activePerson()?.username || 'Mitarbeiter';
const companyName = () => activeBusiness()?.company_name || activeBusiness()?.username || 'Zeiterfassung';
const initials = text => String(text||'AZ').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const logoUrl = () => { const path=activeBusiness()?.company_logo_path; return path ? db.storage.from('company-logos').getPublicUrl(path).data.publicUrl : ''; };
const targetHours = date => { const day=dayDate(date).getDay(); return day >= 1 && day <=4 ? 8 : day===5 ? 5 : 0; };
const isHoliday = date => HOLIDAYS.has(date);
const datePlus = (date, n) => { const result=dayDate(date); result.setDate(result.getDate()+n); return iso(result); };
const diffMinutes = (start,end) => { if(!start || !end)return 0; const [a,b]=[start,end].map(v=>{const t=String(v).slice(0,5).split(':').map(Number);return t[0]*60+t[1];}); return b>=a ? b-a : b+1440-a; };
const addMinutes = (start, amount) => { const [h,m]=String(start||'07:30').slice(0,5).split(':').map(Number); const total=(h*60+m+amount+1440)%1440; return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`; };
const roundedTime = value => { const m=String(value||'').match(/^(\d{1,2}):(\d{2})/); if(!m)return ''; const minutes=Math.max(0,Math.min(1439,Number(m[1])*60+Number(m[2]))); const rounded=Math.round(minutes/15)*15%1440; return `${String(Math.floor(rounded/60)).padStart(2,'0')}:${String(rounded%60).padStart(2,'0')}`; };
const qHours = value => Math.max(0,Math.round(num(value)*4)/4);
const timeOptions = value => `<input name="${value.name}" type="time" step="900" value="${esc(value.value||'')}" data-time-sync="${esc(value.sync||'')}" />`;

function notify(message,error=false){ state.toast={message,error}; render(); clearTimeout(notify.timer); notify.timer=setTimeout(()=>{state.toast=null;render();},3600); }
async function query(request){ const {data,error}=await request; if(error) throw error; return data; }
async function soft(request,fallback=[]){ try{return await query(request);}catch{return fallback;} }
async function perform(message,work){ if(state.busy)return; state.busy=true; render(); try{ await work(); await load(); if(message)notify(message); }catch(error){ notify(error?.message || 'Die Aktion konnte nicht ausgeführt werden.',true); }finally{ state.busy=false; render(); } }

async function load(){
  const {data:{session}}=await db.auth.getSession(); state.session=session;
  if(!session){ state.profile=null;state.people=[];state.data=emptyData();state.booting=false;render();return; }
  const profile=await query(db.from('profiles').select('*').eq('id',session.user.id).single());
  state.profile=profile;
  state.people=await soft(db.from('profiles').select('*').order('username'),[profile]);
  if(!state.people.some(p=>same(p.id,profile.id))) state.people.push(profile);
  if(admin() && !businesses().some(p=>same(p.id,state.selectedBusinessId))) state.selectedBusinessId=businesses()[0]?.id || null;
  const rows=await Promise.all([
    soft(db.from('customers').select('*').order('name')),soft(db.from('time_entries').select('*').order('work_date',{ascending:false}).order('start_time')),
    soft(db.from('work_days').select('*')),soft(db.from('work_orders').select('*').order('work_date',{ascending:false}).order('created_at',{ascending:false})),
    soft(db.from('work_order_items').select('*')),soft(db.from('materials').select('*').order('name')),soft(db.from('mailbox_messages').select('*').order('created_at',{ascending:false})),
    soft(db.from('vacation_requests').select('*').order('created_at',{ascending:false})),soft(db.from('appointments').select('*').order('event_date')),soft(db.from('work_order_documents').select('*')),soft(db.from('employee_payslips').select('*').order('created_at',{ascending:false}))
  ]);
  [state.data.customers,state.data.entries,state.data.days,state.data.orders,state.data.items,state.data.materials,state.data.messages,state.data.vacations,state.data.appointments,state.data.documents,state.data.payslips]=rows;
  state.booting=false; render();
}

function own(rows){ return rows.filter(row=>same(row.employee_id,activeEmployeeId())); }
function dayStatusFor(employeeId,date){ const sick=state.data.days.find(row=>same(row.employee_id,employeeId)&&same(row.work_date,date)&&num(row.sick)>0); const vacation=state.data.vacations.find(row=>same(row.employee_id,employeeId)&&row.status==='approved' && row.start_date<=date && row.end_date>=date); const requested=state.data.vacations.find(row=>same(row.employee_id,employeeId)&&row.status==='requested' && row.start_date<=date && row.end_date>=date); return {sick:Boolean(sick),vacation:Boolean(vacation),requested:Boolean(requested),holiday:isHoliday(date)}; }
function dayStatus(date){ return dayStatusFor(activeEmployeeId(),date); }
function lockedFor(employeeId,date){ const s=dayStatusFor(employeeId,date); return s.sick || s.vacation || s.holiday; }
function locked(date){ return lockedFor(activeEmployeeId(),date); }
function totalOvertime(){ const map=new Map(); own(state.data.entries).forEach(row=>map.set(row.work_date,(map.get(row.work_date)||0)+num(row.executed_hours))); return [...map.entries()].reduce((sum,[date,value])=>sum+(targetHours(date)?value-targetHours(date):0),0); }
function vacationLeft(){ const used=own(state.data.vacations).filter(v=>v.status==='approved').reduce((s,v)=>s+num(v.requested_days),0); return Math.max(0,num(activePerson()?.vacation_allowance)-used); }
function totalSick(){ return own(state.data.days).reduce((s,row)=>s+num(row.sick),0); }
function weekDates(){ const base=dayDate(state.date); const shift=(base.getDay()+6)%7; base.setDate(base.getDate()-shift); return [0,1,2,3,4].map(n=>iso(new Date(base.getFullYear(),base.getMonth(),base.getDate()+n,12))); }

function loginView(){ return `<main class="login-shell"><section class="login-card"><h1 class="login-title">Zeiterfassung</h1><div class="company-mark">AZ</div><p class="subtle">Anmeldung zum Firmenkonto</p><form id="login-form"><label class="field"><span>Firma</span><input name="company" autocomplete="organization" placeholder="Firmenname" /></label><label class="field"><span>Benutzername</span><input name="username" autocomplete="username" required placeholder="Benutzername" /></label><label class="field"><span>Passwort</span><input name="password" type="password" autocomplete="current-password" required placeholder="Passwort" /></label><button class="primary full" ${state.busy?'disabled':''}>Anmelden</button></form><div class="login-help"><button class="link-button" data-action="forgot">Passwort vergessen</button></div></section></main>`; }
function allowed(item){ return manager() || state.profile?.menu_permissions?.[item] !== false; }
function menuHtml(){ const items=MENU.filter(([id])=>allowed(id)).map(([id,label])=>`<button class="menu-item ${state.view===id?'active':''}" data-action="view" data-view="${id}">${label}</button>`).join(''); return `<div class="menu-wrap"><button class="menu-trigger" data-action="menu">☰ <span>Menü</span></button>${state.menu?`<div class="menu-panel"><div class="menu-title">Navigation</div>${items}<div class="menu-divider"></div><button class="menu-item" data-action="logout">Abmelden</button></div>`:''}</div>`; }
function topbar(){ const logo=logoUrl(); return `<header class="topbar"><div class="brand-logo">${logo?`<img src="${esc(logo)}" alt="Firmenlogo">`:initials(companyName())}</div><div class="welcome"><h1>Willkommen${state.profile ? `, ${esc(activeName())}`:''}</h1><p>${admin()?'Administrator · übergeordnete Kontoverwaltung':business()?'Geschäftskonto · Betriebsübersicht':'Mitarbeiterkonto'} · ${esc(companyName())}</p></div>${menuHtml()}</header>`; }
function peopleCard(){ if(!manager()) return `<aside class="side-card"><span class="profile-badge">${esc(state.profile?.username)}</span><h2>Mein Bereich</h2><p class="subtle">Deine Einträge und Termine.</p></aside>`; const options=selectablePeople().map(p=>`<option value="${p.id}" ${same(p.id,activeEmployeeId())?'selected':''}>${esc(p.username)}${p.role==='administrator'?' (Administrator)':p.role==='business'?' (Geschäftskonto)':''}</option>`).join(''); const businessSelect=admin()?`<label class="field"><span>Geschäftskonto</span><select data-action="business-select"><option value="">Geschäftskonto auswählen</option>${businesses().map(p=>`<option value="${p.id}" ${same(p.id,currentBusinessId())?'selected':''}>${esc(p.company_name||p.username)}</option>`).join('')}</select></label>`:''; return `<aside class="side-card">${businessSelect}<h2>Ausgewählte Person</h2><select class="person-select" data-action="person-select">${options}</select><div class="list">${selectablePeople().slice(0,7).map(p=>`<div class="mini"><b>${esc(p.username)}</b><span>${hours(state.data.entries.filter(x=>same(x.employee_id,p.id)).reduce((s,x)=>s+num(x.executed_hours),0))} erfasst</span></div>`).join('')||'<p class="subtle">Noch keine Mitarbeiter angelegt.</p>'}</div></aside>`; }
function layout(content){ return `<main class="app-shell">${topbar()}<div class="dashboard"><section class="main-card">${content}</section>${peopleCard()}</div>${state.toast?`<div class="toast ${state.toast.error?'error':''}">${esc(state.toast.message)}</div>`:''}</main>`; }

function dateChips(){ const names=['Mo','Di','Mi','Do','Fr']; return `<div class="week">${weekDates().map((date,index)=>`<button class="day-chip ${same(date,state.date)?'active':''} ${isHoliday(date)?'holiday':''}" data-action="date" data-date="${date}"><b>${names[index]}</b><span>${compactDate(date)}</span></button>`).join('')}</div>`; }
function stats(){ return `<div class="stats"><article class="stat"><span>Überstunden</span><strong>${hours(totalOvertime())}</strong></article><article class="stat"><span>Urlaubstage vorhanden</span><strong>${num(vacationLeft()).toLocaleString('de-DE')}</strong></article><article class="stat"><span>Krankheitstage gesamt</span><strong>${num(totalSick()).toLocaleString('de-DE')}</strong></article></div>`; }
function customerOptions(selected=''){ return `<option value="">Kunde eingeben oder auswählen</option>${state.data.customers.map(c=>`<option value="${c.id}" ${same(c.id,selected)?'selected':''}>${esc(c.name)}</option>`).join('')}`; }
function timeForm(){ const records=own(state.data.entries).filter(row=>same(row.work_date,state.date)); const previous=records.at(-1)?.end_time?.slice(0,5) || '07:30'; const cannot=locked(state.date); const status=dayStatus(state.date); const rows=records.map(row=>`<article class="record"><div><b>${esc(row.customer_name||'Ohne Kundenname')}</b><small>${timeLabel(row.start_time)} – ${timeLabel(row.end_time)} · Pause ${hours(row.pause_hours)} · ${hours(row.executed_hours)}</small></div><div class="record-actions"><button class="icon-button delete" data-action="delete-time" data-id="${row.id}" title="Eintrag löschen">Löschen</button></div></article>`).join(''); return `<div class="section-head"><div><h2>Zeiterfassung</h2><p>${dateLabel(state.date)} · ${esc(activeName())}</p></div></div>${dateChips()}${stats()}${cannot?`<div class="notice">${status.sick?'Krankheitstag':status.vacation?'Genehmigter Urlaub':'Feiertag'}: Für diesen Tag können keine Arbeitszeiten oder Arbeitsscheine angelegt werden.</div>`:`<form id="time-form"><div class="entry-grid"><label class="field wide"><span>Kunde</span><input name="customerName" list="customers" placeholder="Kundenname eingeben" required><datalist id="customers">${state.data.customers.map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist></label><label class="field"><span>Arbeitsbeginn</span>${timeOptions({name:'start',value:previous,sync:'start'})}</label><label class="field"><span>Arbeitsende</span>${timeOptions({name:'end',value:'',sync:'end'})}</label><label class="field"><span>Pause</span><input name="pause" type="number" min="0" step="0.25" value="0" data-time-sync="pause"></label><label class="field"><span>Ausgeführte Stunden</span><input name="hours" type="number" min="0.25" step="0.25" placeholder="z. B. 2,50" data-time-sync="hours"></label><label class="field"><span>Beschreibung</span><input name="note" maxlength="160" placeholder="Optional"></label></div><div class="form-actions"><button class="primary" ${state.busy?'disabled':''}>Zeiterfassung bestätigen</button></div></form>`}<div class="timeline">${rows||'<div class="blank">Noch keine Arbeitszeiten an diesem Tag.</div>'}</div>`; }
function orderForm(){ const lockedDay=locked(state.date); const orders=own(state.data.orders).filter(row=>same(row.work_date,state.date)); const orderHtml=orders.map(order=>{const items=state.data.items.filter(item=>same(item.work_order_id,order.id));const docs=state.data.documents.filter(doc=>same(doc.work_order_id,order.id));return `<article class="order-card"><header><div><h3>${esc(order.customer_name||'Ohne Kundenname')}</h3><p>${esc(order.title||'Arbeitsauftrag')} · ${timeLabel(order.start_time)}–${timeLabel(order.end_time)} · ${hours(order.executed_hours)}</p></div><button class="icon-button delete" data-action="delete-order" data-id="${order.id}">Löschen</button></header>${order.documentation?`<p>Dokumentation: ${esc(order.documentation)}</p>`:''}${items.length?`<p>Material: ${items.map(i=>`${esc(i.position_name)} (${num(i.quantity)})`).join(', ')}</p>`:''}${docs.length?`<p>Dateien: ${docs.map(d=>esc(d.file_name)).join(', ')}</p>`:''}</article>`;}).join(''); return `<div class="section-head"><div><h2>Arbeitsscheine von ${esc(activeName())}</h2><p>zu ${dateLabel(state.date)}</p></div></div>${lockedDay?`<div class="notice">Für diesen Tag ist keine Arbeitsleistung möglich.</div>`:`<form id="order-form"><div class="entry-grid"><label class="field wide"><span>Beschreibung</span><input name="title" required maxlength="160" placeholder="Beschreibung des Arbeitsauftrags"></label><label class="field wide"><span>Arbeitsauftrag Kunde</span><input name="customerName" list="order-customers" required placeholder="Kundenname eingeben"><datalist id="order-customers">${state.data.customers.map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist></label><label class="field"><span>Mitarbeiter</span><select name="employee">${(manager()?employeePeople():[state.profile]).concat(business()?[state.profile]:[]).filter((p,i,a)=>p&&a.findIndex(q=>same(q.id,p.id))===i).map(p=>`<option value="${p.id}" ${same(p.id,activeEmployeeId())?'selected':''}>${esc(p.username)}</option>`).join('')}</select></label><label class="field"><span>Arbeitsbeginn</span>${timeOptions({name:'start',value:orders.at(-1)?.end_time?.slice(0,5)||'07:30',sync:'start'})}</label><label class="field"><span>Arbeitsende</span>${timeOptions({name:'end',value:'',sync:'end'})}</label><label class="field"><span>Pausenstunden</span><input name="pause" type="number" min="0" step="0.25" value="0" data-time-sync="pause"></label><label class="field"><span>Ausgeführte Stunden</span><input name="hours" type="number" min="0.25" step="0.25" data-time-sync="hours"></label><label class="field wide"><span>Dokumentation</span><textarea name="documentation" placeholder="Arbeitsablauf, Hinweise oder Besonderheiten"></textarea></label><label class="field wide"><span>Dokument Upload</span><input name="documents" type="file" multiple accept="image/*,.pdf,.doc,.docx,.xlsx"></label></div><div class="settings-block"><h3>Material</h3><div id="materials-inputs"><div class="material-row"><label class="field"><span>Material</span><input name="materialName" placeholder="Artikel eingeben"></label><label class="field"><span>Stückzahl</span><input name="quantity" type="number" min="0" step="0.25" value="1"></label></div></div></div><div class="form-actions"><button type="button" class="secondary" data-action="more-material">Weiteres Material</button><button class="primary" ${state.busy?'disabled':''}>Arbeitsschein bestätigen</button></div></form>`}<div class="timeline">${orderHtml||'<div class="blank">Für diesen Tag liegen noch keine Arbeitsscheine vor.</div>'}</div>`; }
function monthGrid(){ const first=new Date(state.year,state.month,1,12), last=new Date(state.year,state.month+1,0,12); const start=(first.getDay()+6)%7; const cells=[]; for(let i=0;i<start;i++)cells.push('<div class="cal-day out"></div>'); for(let day=1;day<=last.getDate();day++){const d=iso(new Date(state.year,state.month,day,12)),status=dayStatus(d), cls=`${same(d,state.date)?' selected':''}`; let dots=''; if(status.sick)dots='<i class="dot sick"></i>';else if(status.vacation)dots='<i class="dot"></i>';else if(status.requested)dots='<i class="dot requested"></i>'; cells.push(`<button class="cal-day${cls}" data-action="date" data-date="${d}">${day}${dots}</button>`);} const title=new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(first); return `<div class="calendar-head"><button class="secondary" data-action="month" data-direction="-1">‹</button><b>${title}</b><button class="secondary" data-action="month" data-direction="1">›</button></div><div class="calendar-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div>`; }
function calendarView(){ const status=dayStatus(state.date), orders=own(state.data.orders).filter(o=>same(o.work_date,state.date)); const vacation=own(state.data.vacations).find(v=>v.start_date<=state.date&&v.end_date>=state.date&&v.status!=='rejected'); return `<div class="section-head"><div><h2>Kalender</h2><p>${dateLabel(state.date)}</p></div></div>${stats()}${monthGrid()}<div class="calendar-actions">${(!status.sick && (manager()||same(activeEmployeeId(),state.profile.id)))?`<button class="danger" data-action="sick">Krank melden</button>`:''}${status.sick&&manager()?`<button class="secondary" data-action="unsick">Krankheitstag entfernen</button>`:''}<button class="primary" data-action="vacation">Urlaub beantragen</button><button class="secondary" data-action="appointment">Kundentermin vormerken</button></div><div class="detail-cards">${orders.map(o=>`<article class="detail-card"><b>Arbeitsschein</b><br>${esc(o.customer_name)} · ${esc(o.title||'Arbeitsauftrag')}</article>`).join('')}${vacation?`<article class="detail-card vacation"><b>${vacation.status==='approved'?'Urlaub genehmigt':'Urlaub beantragt'}</b><br>${dateLabel(vacation.start_date)} bis ${dateLabel(vacation.end_date)}</article>`:''}${status.sick?'<article class="detail-card sick"><b>Krank</b><br>Für diesen Tag ist keine Arbeit oder Urlaubsplanung möglich.</article>':''}${!orders.length&&!vacation&&!status.sick?'<div class="blank">Für diesen Tag ist noch nichts eingetragen.</div>':''}</div>`; }

function customerFields(customer={}){ const f=customer.custom_fields||{}; const val=(key)=>esc(f[key]||''); return `<form id="customer-form"><input type="hidden" name="id" value="${esc(customer.id||'')}"><div class="customer-grid"><label class="field"><span>Name</span><input name="lastName" value="${esc(f.lastName||customer.name||'')}" required></label><label class="field"><span>Vorname</span><input name="firstName" value="${val('firstName')}"></label><label class="field"><span>Straße</span><input name="street" value="${val('street')}"></label><label class="field"><span>Hausnummer</span><input name="number" value="${val('number')}"></label><label class="field"><span>Ort</span><input name="city" value="${val('city')}"></label><label class="field"><span>Postleitzahl</span><input name="zip" value="${val('zip')}"></label><label class="field"><span>Tel. privat</span><input name="phonePrivate" value="${val('phonePrivate')}"></label><label class="field"><span>Tel. Mobil</span><input name="phoneMobile" value="${val('phoneMobile')}"></label><label class="field full-row"><span>E-Mail Adresse</span><input name="email" type="email" value="${val('email')}"></label><label class="field full-row"><span>Zusätzliche Angaben</span><textarea name="extra" placeholder="Weitere Eingabefelder oder Hinweise">${val('extra')}</textarea></label></div><div class="form-actions">${customer.id?`<button type="button" class="danger" data-action="delete-customer" data-id="${customer.id}">Kunde löschen</button>`:''}<button type="button" class="secondary" data-action="cancel-customer">Abbrechen</button><button class="primary">Kunde bestätigen</button></div></form>`; }
function customersView(){ const selected=state.data.customers.find(c=>same(c.id,state.selectedCustomerId)); const list=state.data.customers.map(c=>{const total=state.data.entries.filter(e=>same(e.customer_id,c.id)).reduce((s,e)=>s+num(e.executed_hours),0);return `<button class="customer-row" data-action="customer" data-id="${c.id}"><span><b>${esc(c.name)}</b><small>${esc(c.custom_fields?.city||'')}</small></span><span>${hours(total)}</span></button>`;}).join(''); return `<div class="section-head"><div><h2>${selected?'Kunde bearbeiten':'Kundenliste'}</h2><p>${selected?'Stammdaten und Stunden pro Jahr':'Kunden hinzufügen oder auswählen'}</p></div>${selected?'<button class="secondary" data-action="new-customer">Neuer Kunde</button>':''}</div>${selected?`<div class="notice">Insgesamt ausgeführte Stunden: ${hours(state.data.entries.filter(e=>same(e.customer_id,selected.id)).reduce((s,e)=>s+num(e.executed_hours),0))}</div>${customerFields(selected)}`:`${customerFields()}<div class="settings-block"><h3>Vorhandene Kunden</h3><div class="customer-list">${list||'<div class="blank">Noch keine Kunden angelegt.</div>'}</div></div>`}`; }
function materialsView(){ const list=state.data.materials.filter(m=>m.active!==false).map(m=>`<article class="record"><div><b>${esc(m.name)}</b><small>${num(m.unit_price).toLocaleString('de-DE',{style:'currency',currency:'EUR'})}</small></div>${manager()?`<button class="icon-button delete" data-action="delete-material" data-id="${m.id}">Löschen</button>`:''}</article>`).join(''); return `<div class="section-head"><div><h2>Materialliste</h2><p>Artikel werden im Arbeitsschein als Text eingegeben.</p></div></div>${manager()?`<form id="material-form"><div class="two-col"><label class="field"><span>Material</span><input name="name" required placeholder="Artikelbezeichnung"></label><label class="field"><span>Preis €</span><input name="price" type="number" min="0" step="0.01" placeholder="Optional"></label></div><div class="form-actions"><button class="primary">Material hinzufügen</button></div></form>`:'<div class="notice">Materialien können im Arbeitsschein vorgeschlagen werden.</div>'}<div class="timeline">${list||'<div class="blank">Noch keine Materialien vorhanden.</div>'}</div>`; }
function mailboxView(){ const ownMessages=state.data.messages.filter(m=>same(m.recipient_id,state.profile.id)); const filtered=ownMessages.filter(m=>state.folder==='trash'?Boolean(m.deleted_at):state.folder==='read'?Boolean(m.read_at)&&!m.deleted_at:state.folder==='unread'?!m.read_at&&!m.deleted_at:!m.deleted_at); const selected=filtered.find(m=>same(m.id,state.openMessageId))||ownMessages.find(m=>same(m.id,state.openMessageId)); const rows=filtered.map(m=>`<button class="message ${m.read_at?'':'unread'}" data-action="message" data-id="${m.id}"><b>${esc(m.title)}</b><small>${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(m.created_at))}</small></button>`).join(''); const body=selected?.body||{}; const text=body.message||body.note||(body.start_date?`${body.start_date||''} ${body.end_date?`bis ${body.end_date}`:''}`:'Keine weiteren Angaben.'); return `<div class="section-head"><div><h2>Postfach</h2><p>Mitteilungen und Lohnabrechnungen</p></div></div><div class="mail-tabs">${[['all','Alle'],['read','Gelesen'],['unread','Ungelesen'],['trash','Papierkorb'],['drafts','Entwürfe']].map(([id,label])=>`<button class="tab ${state.folder===id?'active':''}" data-action="folder" data-folder="${id}">${label}</button>`).join('')}</div><div class="timeline">${state.folder==='drafts'?'<div class="blank">Keine Entwürfe.</div>':rows||'<div class="blank">Dieser Ordner ist leer.</div>'}</div>${selected?`<section class="message-detail"><b>${esc(selected.title)}</b><p>${esc(text)}</p>${body.payslip_path?`<div class="form-actions"><button class="primary" data-action="payslip-download" data-path="${esc(body.payslip_path)}" data-name="${esc(body.file_name||'Lohnabrechnung')}">Datei herunterladen</button></div>`:''}${selected.message_type==='vacation_request'&&manager()?`<div class="form-actions"><button class="primary" data-action="vacation-decision" data-id="${selected.id}" data-decision="approved">Genehmigen</button><button class="danger" data-action="vacation-decision" data-id="${selected.id}" data-decision="rejected">Ablehnen</button></div>`:''}<div class="form-actions"><button class="secondary" data-action="mail-delete" data-id="${selected.id}">Nachricht löschen</button></div></section>`:''}`; }
function settingsView(){ if(!manager())return `<div class="section-head"><div><h2>Einstellungen</h2><p>Dein Konto wird durch das Geschäftskonto verwaltet.</p></div></div><div class="notice">Mitarbeiter können ihr Passwort nicht selbst ändern.</div>`; const selected=state.people.find(p=>same(p.id,activeEmployeeId()))||state.profile; const permission=selected.menu_permissions||defaultPermissions; const businessEditor=admin()?`<section class="settings-block"><h3>Neues Geschäftskonto</h3><form id="business-form"><div class="two-col"><label class="field"><span>Firma</span><input name="companyName" required></label><label class="field"><span>Benutzername</span><input name="username" required></label><label class="field"><span>Passwort</span><input name="password" type="password" minlength="8" required></label></div><div class="form-actions"><button class="primary">Geschäftskonto anlegen</button></div></form></section>`:''; const employeeEditor=`<section class="settings-block"><h3>Mitarbeiter hinzufügen</h3>${!currentBusinessId()?'<div class="notice">Bitte zuerst ein Geschäftskonto auswählen oder anlegen.</div>':`<form id="employee-form"><div class="two-col"><label class="field"><span>Benutzername</span><input name="username" required></label><label class="field"><span>Passwort</span><input name="password" type="password" minlength="8" required></label><label class="field"><span>Urlaubstage vorhanden</span><input name="allowance" type="number" min="0" step="0.5" value="30"></label></div><p class="subtle">Sichtbare Menüs für diesen Mitarbeiter</p><div class="permission-grid">${[['time','Zeiterfassung'],['customers','Kunden'],['orders','Arbeitsscheine'],['calendar','Kalender']].map(([id,label])=>`<label class="check"><input type="checkbox" name="perm-${id}" checked> ${label}</label>`).join('')}</div><div class="form-actions"><button class="primary">Mitarbeiter anlegen</button></div></form>`}</section>`; const editEmployee=selected.role==='employee'?`<section class="settings-block"><h3>Mitarbeiter bearbeiten: ${esc(selected.username)}</h3><form id="employee-update-form"><input type="hidden" name="id" value="${selected.id}"><div class="two-col"><label class="field"><span>Benutzername</span><input name="username" value="${esc(selected.username)}"></label><label class="field"><span>Neues Passwort</span><input name="password" type="password" minlength="8" placeholder="Nur bei Änderung"></label><label class="field"><span>Urlaubstage vorhanden</span><input name="allowance" type="number" min="0" step="0.5" value="${num(selected.vacation_allowance)}"></label></div><p class="subtle">Sichtbare Menüs</p><div class="permission-grid">${[['time','Zeiterfassung'],['customers','Kunden'],['orders','Arbeitsscheine'],['calendar','Kalender']].map(([id,label])=>`<label class="check"><input type="checkbox" name="perm-${id}" ${permission[id]!==false?'checked':''}> ${label}</label>`).join('')}</div><div class="form-actions"><button type="button" class="danger" data-action="delete-employee" data-id="${selected.id}">Mitarbeiter löschen</button><button class="primary">Mitarbeiter speichern</button></div></form></section>`:''; const accountEditor=`<section class="settings-block"><h3>Mein Benutzerkonto</h3><form id="self-form"><div class="two-col"><label class="field"><span>Benutzername</span><input name="username" value="${esc(state.profile.username)}"></label><label class="field"><span>Neues Passwort</span><input name="password" type="password" minlength="8" placeholder="Nur bei Änderung"></label>${business()?`<label class="field"><span>Firma</span><input name="companyName" value="${esc(state.profile.company_name||'')}"></label><label class="field"><span>Firmenlogo</span><input name="logo" type="file" accept="image/*"></label>`:''}<label class="field"><span>Urlaubstage vorhanden</span><input name="allowance" type="number" min="0" step="0.5" value="${num(state.profile.vacation_allowance)}"></label></div><div class="form-actions"><button class="primary">Konto speichern</button></div></form></section>`; const payslip= currentBusinessId()?`<section class="settings-block"><h3>Lohnabrechnung zustellen</h3><form id="payslip-form"><div class="two-col"><label class="field"><span>Mitarbeiter</span><select name="employee">${employeePeople().map(p=>`<option value="${p.id}">${esc(p.username)}</option>`).join('')}</select></label><label class="field"><span>Datei</span><input name="file" type="file" required accept=".pdf,image/*"></label></div><div class="form-actions"><button class="primary">In das Postfach zustellen</button></div></form></section>`:''; const statistic=`<section class="settings-block"><h3>Statistik: ${esc(selected.username)}</h3><div class="stats"><article class="stat"><span>Stunden gesamt</span><strong>${hours(own(state.data.entries).reduce((s,e)=>s+num(e.executed_hours),0))}</strong></article><article class="stat"><span>Urlaub übrig</span><strong>${num(vacationLeft())}</strong></article><article class="stat"><span>Krankheitstage</span><strong>${num(totalSick())}</strong></article></div><div class="form-actions"><button class="secondary" data-action="pdf" data-id="${selected.id}">Daten als PDF herunterladen</button></div></section>`; return `<div class="section-head"><div><h2>Einstellungen</h2><p>Konten, Berechtigungen und Statistik</p></div></div>${accountEditor}${businessEditor}${employeeEditor}${editEmployee}${payslip}${statistic}`; }
function billingView(){ const open=own(state.data.orders).filter(o=>!o.invoiced); return `<div class="section-head"><div><h2>Abrechnungen Kunden</h2><p>Nicht abgerechnete Arbeitsscheine</p></div></div>${open.length?open.map(o=>`<article class="order-card"><b>${esc(o.customer_name)}</b><p>${dateLabel(o.work_date)} · ${esc(o.title||'Arbeitsauftrag')} · ${hours(o.executed_hours)}</p><button class="secondary" data-action="invoice-order" data-id="${o.id}">Als abgerechnet markieren</button></article>`).join(''):'<div class="blank">Alle vorhandenen Arbeitsscheine sind abgerechnet.</div>'}`; }
function invoicesView(){ return `<div class="section-head"><div><h2>Rechnungen</h2><p>Übersicht der abgerechneten Arbeitsscheine</p></div></div>${own(state.data.orders).filter(o=>o.invoiced).map(o=>`<article class="order-card"><b>${esc(o.customer_name)}</b><p>${dateLabel(o.work_date)} · ${hours(o.executed_hours)}</p></article>`).join('')||'<div class="blank">Noch keine abgerechneten Arbeitsscheine.</div>'}`; }
function render(){ if(state.booting){root.innerHTML='<main class="loading">Zeiterfassung wird vorbereitet …</main>';return;} if(!state.session){root.innerHTML=loginView();return;} const views={time:timeForm,orders:orderForm,calendar:calendarView,customers:customersView,materials:materialsView,mail:mailboxView,settings:settingsView,billing:billingView,invoices:invoicesView}; root.innerHTML=layout((views[state.view]||timeForm)()); }

function workTimes(form){
  let start=roundedTime(form.get('start')) || '07:30'; let end=roundedTime(form.get('end')); const pause=qHours(form.get('pause'));
  let executed=qHours(form.get('hours'));
  if(end){ executed=qHours(Math.max(0,diffMinutes(start,end)/60-pause)); }
  else if(executed>0) end=addMinutes(start,Math.round((executed+pause)*60));
  if(!end || executed<=0) throw new Error('Bitte Arbeitsende oder ausgeführte Stunden angeben.');
  return {start,end,pause,executed};
}
function similarCustomer(name){ const needle=normalize(name); return state.data.customers.find(c=>{const n=normalize(c.name);return n===needle||n.includes(needle)||needle.includes(n);}); }
async function ensureCustomer(value,employeeId){ const name=String(value||'').trim(); if(!name)throw new Error('Bitte einen Kundennamen eingeben.'); const existing=state.data.customers.find(c=>normalize(c.name)===normalize(name)); if(existing)return existing; const similar=similarCustomer(name); if(similar && !confirm(`Meinst du den vorhandenen Kunden „${similar.name}“?\nOK: vorhandenen Kunden verwenden · Abbrechen: neuen Kunden anlegen`)) return await createCustomer(name,employeeId); if(similar)return similar; return await createCustomer(name,employeeId); }
async function createCustomer(name,employeeId){ const data=await query(db.from('customers').insert({employee_id:employeeId,name,custom_fields:{lastName:name}}).select().single()); return data; }
async function ensureMaterial(name){ const value=String(name||'').trim(); if(!value)return null; const existing=state.data.materials.find(m=>normalize(m.name)===normalize(value)); if(existing)return existing; const near=state.data.materials.find(m=>normalize(m.name).includes(normalize(value))||normalize(value).includes(normalize(m.name))); if(near && confirm(`Meinst du den vorhandenen Artikel „${near.name}“?\nOK: vorhandenen Artikel verwenden · Abbrechen: neuen Artikel ohne Preis anlegen`)) return near; const material=await query(db.from('materials').insert({name:value,unit_price:0,business_id:currentBusinessId(),active:true}).select().single()); return material; }
function currentMonthChange(direction){ const date=new Date(state.year,state.month+direction,1);state.year=date.getFullYear();state.month=date.getMonth();render(); }
function formMaterialRows(form){ return Array.from(form.querySelectorAll('.material-row')).map(row=>({name:row.querySelector('[name="materialName"]')?.value||'',quantity:qHours(row.querySelector('[name="quantity"]')?.value||0)})).filter(x=>x.name.trim()); }
function syncFields(form,source){ const start=form.querySelector('[name="start"]'), end=form.querySelector('[name="end"]'), pause=form.querySelector('[name="pause"]'), hrs=form.querySelector('[name="hours"]'); if(!start||!end||!pause||!hrs)return; start.value=roundedTime(start.value)||start.value; end.value=roundedTime(end.value)||end.value; const p=qHours(pause.value); if(source==='end'||source==='pause'){ if(start.value&&end.value)hrs.value=qHours(Math.max(0,diffMinutes(start.value,end.value)/60-p)).toFixed(2); } if(source==='hours'||source==='pause'){const h=qHours(hrs.value);if(start.value&&h>0&&(!end.value||source==='hours'))end.value=addMinutes(start.value,Math.round((h+p)*60));} }

root.addEventListener('submit', event=>{ event.preventDefault(); const form=event.target; const data=new FormData(form); if(form.id==='login-form')return login(data); if(form.id==='time-form')return saveTime(data); if(form.id==='order-form')return saveOrder(data,form); if(form.id==='customer-form')return saveCustomer(data); if(form.id==='material-form')return saveMaterial(data); if(form.id==='business-form')return createBusiness(data); if(form.id==='employee-form')return createEmployee(data); if(form.id==='employee-update-form')return updateEmployee(data); if(form.id==='self-form')return saveSelf(data,form); if(form.id==='payslip-form')return sendPayslip(data); });
root.addEventListener('change', event=>{ const target=event.target; if(target.matches('[data-time-sync]'))syncFields(target.form,target.dataset.timeSync); if(target.dataset.action==='person-select'){state.selectedEmployeeId=target.value;render();} if(target.dataset.action==='business-select'){state.selectedBusinessId=target.value;state.selectedEmployeeId=null;render();} });
root.addEventListener('click', event=>{ const button=event.target.closest('[data-action]');if(!button)return; const a=button.dataset.action; if(a==='menu'){state.menu=!state.menu;return render();} if(a==='view'){state.view=button.dataset.view;state.menu=false;state.selectedCustomerId=null;return render();} if(a==='date'){state.date=button.dataset.date;state.month=dayDate(state.date).getMonth();state.year=dayDate(state.date).getFullYear();return render();} if(a==='month')return currentMonthChange(Number(button.dataset.direction)); if(a==='logout')return perform('',()=>db.auth.signOut()); if(a==='forgot')return forgot(); if(a==='delete-time')return removeRow('time_entries',button.dataset.id,'Zeiterfassung gelöscht.'); if(a==='delete-order')return removeOrder(button.dataset.id); if(a==='new-customer'){state.selectedCustomerId=null;return render();} if(a==='customer'){state.selectedCustomerId=button.dataset.id;return render();} if(a==='cancel-customer'){state.selectedCustomerId=null;return render();} if(a==='delete-customer')return removeRow('customers',button.dataset.id,'Kunde gelöscht.'); if(a==='delete-material')return removeRow('materials',button.dataset.id,'Material gelöscht.'); if(a==='more-material')return addMaterialRow(button); if(a==='sick')return markSick(true); if(a==='unsick')return markSick(false); if(a==='vacation')return requestVacation(); if(a==='appointment')return addAppointment(); if(a==='folder'){state.folder=button.dataset.folder;state.openMessageId=null;return render();} if(a==='message')return openMessage(button.dataset.id); if(a==='mail-delete')return trashMessage(button.dataset.id); if(a==='vacation-decision')return decideVacation(button.dataset.id,button.dataset.decision); if(a==='invoice-order')return perform('Arbeitsschein als abgerechnet markiert.',()=>db.from('work_orders').update({invoiced:true}).eq('id',button.dataset.id)); if(a==='delete-employee')return perform('Mitarbeiterkonto sofort gelöscht.',async()=>{const {data,error}=await db.functions.invoke('account-management',{body:{action:'employee-delete',employeeId:button.dataset.id}});if(error)throw error;if(data?.error)throw new Error(data.error);}); if(a==='pdf')return downloadPdf(button.dataset.id); if(a==='payslip-download')return downloadPayslip(button.dataset.path,button.dataset.name); });

async function login(data){ await perform('',async()=>{ const username=String(data.get('username')||'').trim(); if(!username)throw new Error('Bitte Benutzernamen eingeben.'); const {error}=await db.auth.signInWithPassword({email:`${username.toLowerCase()}@arbeitszeit.local`,password:String(data.get('password')||'')}); if(error)throw new Error('Anmeldung nicht möglich. Bitte Benutzernamen und Passwort prüfen.'); }); }
async function forgot(){ const username=prompt('Bitte Benutzernamen eingeben:'); if(!username)return; await perform('Die zuständige Verwaltung wurde informiert.',async()=>{const {error}=await db.functions.invoke('request-password-help',{body:{username}});if(error)throw error;}); }
async function saveTime(data){ await perform('Zeiterfassung sofort gespeichert.',async()=>{ const employee=activeEmployeeId(); if(!employee)throw new Error('Bitte einen Mitarbeiter auswählen.'); if(lockedFor(employee,state.date))throw new Error('Für diesen Tag dürfen keine Arbeitszeiten erfasst werden.'); const customer=await ensureCustomer(data.get('customerName'),employee); const t=workTimes(data); await query(db.from('time_entries').insert({employee_id:employee,work_date:state.date,customer_id:customer.id,customer_name:customer.name,start_time:t.start,end_time:t.end,pause_hours:t.pause,executed_hours:t.executed,calculation_mode:data.get('end')?'end_time':'hours',custom_fields:{note:String(data.get('note')||'')}})); }); }
async function saveOrder(data,form){ await perform('Arbeitsschein und Zeiterfassung sofort gespeichert.',async()=>{ const employee=String(data.get('employee')||activeEmployeeId()); if(!employee)throw new Error('Bitte einen Mitarbeiter auswählen.'); if(lockedFor(employee,state.date))throw new Error('Für diesen Tag darf kein Arbeitsschein angelegt werden.'); const customer=await ensureCustomer(data.get('customerName'),employee); const t=workTimes(data); const order=await query(db.from('work_orders').insert({employee_id:employee,work_date:state.date,customer_id:customer.id,customer_name:customer.name,title:String(data.get('title')||''),start_time:t.start,end_time:t.end,pause_hours:t.pause,executed_hours:t.executed,calculation_mode:data.get('end')?'end_time':'hours',documentation:String(data.get('documentation')||'')}).select().single()); await query(db.from('time_entries').insert({employee_id:employee,work_date:state.date,customer_id:customer.id,customer_name:customer.name,start_time:t.start,end_time:t.end,pause_hours:t.pause,executed_hours:t.executed,calculation_mode:data.get('end')?'end_time':'hours',work_order_id:order.id})); for(const row of formMaterialRows(form)){const material=await ensureMaterial(row.name);await query(db.from('work_order_items').insert({work_order_id:order.id,position_name:row.name,quantity:row.quantity||1,unit_price:num(material?.unit_price),material_id:material?.id||null}));} for(const file of Array.from(form.querySelector('[name="documents"]')?.files||[])){const safeName=file.name.replace(/[^A-Za-z0-9._-]/g,'_');const path=`${employee}/${order.id}-${Date.now()}-${safeName}`;const {error:uploadError}=await db.storage.from('work-order-documents').upload(path,file);if(uploadError)throw uploadError;await query(db.from('work_order_documents').insert({work_order_id:order.id,employee_id:employee,file_path:path,file_name:file.name,mime_type:file.type||null}));} }); }
async function saveCustomer(data){ await perform('Kundendaten sofort gespeichert.',async()=>{const last=String(data.get('lastName')||'').trim(),first=String(data.get('firstName')||'').trim();if(!last)throw new Error('Bitte den Namen eingeben.');const fields={lastName:last,firstName:first,street:String(data.get('street')||''),number:String(data.get('number')||''),city:String(data.get('city')||''),zip:String(data.get('zip')||''),phonePrivate:String(data.get('phonePrivate')||''),phoneMobile:String(data.get('phoneMobile')||''),email:String(data.get('email')||''),extra:String(data.get('extra')||'')};const name=`${last}${first?`, ${first}`:''}`;const id=String(data.get('id')||'');if(id)await query(db.from('customers').update({name,custom_fields:fields}).eq('id',id));else await query(db.from('customers').insert({employee_id:activeEmployeeId()||state.profile.id,name,custom_fields:fields}));state.selectedCustomerId=null;}); }
async function saveMaterial(data){ await perform('Material sofort hinzugefügt.',async()=>{const name=String(data.get('name')||'').trim();if(!name)throw new Error('Bitte Material eingeben.');const existing=state.data.materials.find(m=>normalize(m.name)===normalize(name));const values={name,unit_price:num(data.get('price')),active:true,business_id:currentBusinessId()};if(existing)await query(db.from('materials').update(values).eq('id',existing.id));else await query(db.from('materials').insert(values));}); }
async function removeRow(table,id,message){ await perform(message,()=>db.from(table).delete().eq('id',id)); }
async function removeOrder(id){ await perform('Arbeitsschein und zugehörige Zeiterfassung sofort gelöscht.',async()=>{await query(db.from('time_entries').delete().eq('work_order_id',id));await query(db.from('work_order_items').delete().eq('work_order_id',id));await query(db.from('work_orders').delete().eq('id',id));}); }
function addMaterialRow(button){ const area=button.closest('form').querySelector('#materials-inputs');const row=document.createElement('div');row.className='material-row';row.innerHTML='<label class="field"><span>Material</span><input name="materialName" placeholder="Artikel eingeben"></label><label class="field"><span>Stückzahl</span><input name="quantity" type="number" min="0" step="0.25" value="1"></label>';area.append(row);row.querySelector('input').focus(); }
async function markSick(value){ await perform(value?'Krankheitstag sofort eingetragen.':'Krankheitstag sofort entfernt.',async()=>{const employee=activeEmployeeId();if(!employee)throw new Error('Bitte Mitarbeiter auswählen.');if(!manager()&&!same(employee,state.profile.id))throw new Error('Mitarbeiter können nur sich selbst krank melden.');if(value)await query(db.from('work_days').upsert({employee_id:employee,work_date:state.date,sick:1,vacation:0},{onConflict:'employee_id,work_date'}));else await query(db.from('work_days').delete().eq('employee_id',employee).eq('work_date',state.date));}); }
async function requestVacation(){ const start=prompt('Urlaub von (JJJJ-MM-TT):',state.date);if(!start)return;const end=prompt('Urlaub bis (JJJJ-MM-TT):',start);if(!end)return;await perform('Urlaubsantrag wurde sofort übermittelt.',async()=>{const {data,error}=await db.functions.invoke('vacation-workflow',{body:{action:'request',startDate:start,endDate:end}});if(error)throw error;if(data?.error)throw new Error(data.error);}); }
async function addAppointment(){ const customer=prompt('Kundenname für den Termin:');if(!customer)return;const title=prompt('Terminbezeichnung:','Kundentermin');if(!title)return;await perform('Kundentermin sofort vorgemerkt.',()=>db.from('appointments').insert({employee_id:activeEmployeeId(),event_date:state.date,customer_name:customer,title})); }
async function openMessage(id){ await perform('',async()=>{state.openMessageId=id;const message=state.data.messages.find(m=>same(m.id,id));if(message&&!message.read_at)await query(db.from('mailbox_messages').update({read_at:new Date().toISOString()}).eq('id',id));}); }
async function trashMessage(id){ await perform('Nachricht in den Papierkorb verschoben.',async()=>{await query(db.from('mailbox_messages').update({deleted_at:new Date().toISOString()}).eq('id',id));state.openMessageId=null;}); }
async function decideVacation(messageId,decision){ await perform(decision==='approved'?'Urlaub genehmigt.':'Urlaub abgelehnt.',async()=>{const message=state.data.messages.find(m=>same(m.id,messageId));const requestId=message?.body?.request_id;if(!requestId)throw new Error('Der Urlaubsantrag fehlt.');const {data,error}=await db.functions.invoke('vacation-workflow',{body:{action:'decide',requestId,status:decision}});if(error)throw error;if(data?.error)throw new Error(data.error);await query(db.from('mailbox_messages').update({read_at:new Date().toISOString()}).eq('id',messageId));}); }
async function createBusiness(data){ await perform('Geschäftskonto sofort angelegt.',async()=>{const {data:reply,error}=await db.functions.invoke('account-management',{body:{action:'business-create',username:String(data.get('username')||''),password:String(data.get('password')||''),companyName:String(data.get('companyName')||'')}});if(error)throw error;if(reply?.error)throw new Error(reply.error);state.selectedBusinessId=reply?.business?.id||null;}); }
async function createEmployee(data){ await perform('Mitarbeiterkonto sofort angelegt.',async()=>{const permissions={};['time','customers','orders','calendar'].forEach(key=>permissions[key]=data.get(`perm-${key}`)==='on');const {data:reply,error}=await db.functions.invoke('account-management',{body:{action:'employee-create',businessId:currentBusinessId(),username:String(data.get('username')||''),password:String(data.get('password')||''),menuPermissions:permissions}});if(error)throw error;if(reply?.error)throw new Error(reply.error);const id=reply?.employee?.id;if(id)await query(db.from('profiles').update({vacation_allowance:num(data.get('allowance'))}).eq('id',id));}); }
async function updateEmployee(data){ await perform('Mitarbeiterkonto sofort gespeichert.',async()=>{const permissions={};['time','customers','orders','calendar'].forEach(key=>permissions[key]=data.get(`perm-${key}`)==='on');const {data:reply,error}=await db.functions.invoke('account-management',{body:{action:'employee-update',employeeId:String(data.get('id')),username:String(data.get('username')||''),password:String(data.get('password')||''),vacationAllowance:num(data.get('allowance')),menuPermissions:permissions}});if(error)throw error;if(reply?.error)throw new Error(reply.error);}); }
async function saveSelf(data,form){ await perform('Konto sofort gespeichert.',async()=>{const body={action:'self-update',username:String(data.get('username')||''),password:String(data.get('password')||''),vacationAllowance:num(data.get('allowance'))};if(business()){body.companyName=String(data.get('companyName')||'');const file=form.querySelector('[name="logo"]')?.files?.[0];if(file){const safeName=file.name.replace(/[^A-Za-z0-9._-]/g,'_');const path=`${state.profile.id}/${Date.now()}-${safeName}`;const {error:uploadError}=await db.storage.from('company-logos').upload(path,file,{upsert:false});if(uploadError)throw uploadError;body.companyLogoPath=path;}}const {data:reply,error}=await db.functions.invoke('account-management',{body});if(error)throw error;if(reply?.error)throw new Error(reply.error);}); }
async function sendPayslip(data){ await perform('Lohnabrechnung sofort in das Postfach gestellt.',async()=>{const file=data.get('file');const employeeId=String(data.get('employee')||'');if(!(file instanceof File)||!employeeId)throw new Error('Bitte Mitarbeiter und Datei auswählen.');const businessId=currentBusinessId();const safeName=file.name.replace(/[^A-Za-z0-9._-]/g,'_');const path=`${businessId}/${employeeId}/${Date.now()}-${safeName}`;const {error:uploadError}=await db.storage.from('employee-payslips').upload(path,file);if(uploadError)throw uploadError;await query(db.from('employee_payslips').insert({business_id:businessId,employee_id:employeeId,uploaded_by:state.profile.id,file_path:path,file_name:file.name,mime_type:file.type||null}));await query(db.from('mailbox_messages').insert({recipient_id:employeeId,sender_id:state.profile.id,message_type:'info',title:'Neue Lohnabrechnung',body:{message:'Eine neue Lohnabrechnung steht zum Herunterladen bereit.',payslip_path:path,file_name:file.name}}));}); }
async function downloadPayslip(path,name){const {data,error}=await db.storage.from('employee-payslips').download(path);if(error){notify('Die Datei konnte nicht heruntergeladen werden.',true);return;}const url=URL.createObjectURL(data);const link=document.createElement('a');link.href=url;link.download=name||'Lohnabrechnung';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadPdf(id){const person=state.people.find(p=>same(p.id,id))||state.profile;const rows=state.data.entries.filter(e=>same(e.employee_id,id));const body=[`Zeiterfassung – ${person.username}`,`Arbeitsstunden gesamt: ${hours(rows.reduce((s,e)=>s+num(e.executed_hours),0))}`,`Überstunden: ${hours(totalOvertime())}`,`Krankheitstage: ${num(totalSick())}`,`Urlaubstage vorhanden: ${num(vacationLeft())}`,'',...rows.map(e=>`${dateLabel(e.work_date)} | ${e.customer_name} | ${hours(e.executed_hours)}`)];const escaped=body.map(line=>String(line).replace(/[()\\]/g,'\\$&'));const stream=['BT','/F1 12 Tf','50 790 Td',...escaped.flatMap((line,i)=>i?['0 -18 Td',`(${line}) Tj`]:[`(${line}) Tj`]),'ET'].join('\n');const pdf=`%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Count 1/Kids[3 0 R]>>endobj\n3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 595 842]/Resources<</Font<</F1 4 0 R>>>>/Contents 5 0 R>>endobj\n4 0 obj<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>endobj\n5 0 obj<</Length ${stream.length}>>stream\n${stream}\nendstream\nendobj\ntrailer<</Root 1 0 R>>\n%%EOF`;const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));const link=document.createElement('a');link.href=url;link.download=`Zeiterfassung-${person.username}.pdf`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

window.addEventListener('error',()=>{if(!root.textContent?.trim())root.innerHTML='<main class="loading">Die App wird neu geladen …</main>';});

async function startApplication(){
  let clientModule;
  try {
    clientModule = await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');
  } catch (firstError) {
    clientModule = await import('https://esm.sh/@supabase/supabase-js@2');
  }
  db = clientModule.createClient(config.supabaseUrl, config.supabasePublishableKey);
  db.auth.onAuthStateChange(()=>{setTimeout(()=>load().catch(()=>{state.booting=false;state.session=null;notify('Die Anmeldung konnte nicht vorbereitet werden.',true);}),0);});
  await load();
}

async function syncFromServer(){
  if (!state.session || state.busy || state.syncing) return;
  state.syncing = true;
  try { await load(); } catch { /* Die nächste Aktualisierung versucht es erneut. */ } finally { state.syncing = false; }
}

window.addEventListener('focus', syncFromServer);
document.addEventListener('visibilitychange', () => { if (!document.hidden) syncFromServer(); });
setInterval(syncFromServer, 15000);

startApplication().catch(()=>{state.booting=false;root.innerHTML='<main class="loading">Die Anmeldung konnte nicht vorbereitet werden. Bitte die Seite neu laden.</main>';});

